    val g1b: String get() = I18n.t("ui.g1b", "\u0412\u044b\u043f\u0438\u0448\u0438\u0442\u0435 \u043b\u044e\u0434\u0435\u0439, \u0443\u0447\u0440\u0435\u0436\u0434\u0435\u043d\u0438\u044f \u0438 \u043a\u043e\u043d\u0446\u0435\u043f\u0446\u0438\u0438, \u043d\u0430 \u043a\u043e\u0442\u043e\u0440\u044b\u0435 \u0435\u0441\u0442\u044c \u043e\u0431\u0438\u0434\u0430. \u041d\u0430 \u044d\u0442\u043e\u043c \u044d\u0442\u0430\u043f\u0435 \u2014 \u0442\u043e\u043b\u044c\u043a\u043e \u0438\u043c\u0435\u043d\u0430, \u0431\u0435\u0437 \u043f\u043e\u0434\u0440\u043e\u0431\u043d\u043e\u0439 \u0438\u0441\u0442\u043e\u0440\u0438\u0438.")
    val g2t: String get() = I18n.t("ui.g2t", "\u041f\u0443\u043d\u043a\u0442 \u0411 \u2014 \u0441\u0438\u0442\u0443\u0430\u0446\u0438\u044f")
